import {createHmac} from 'node:crypto';
export function paymentFixture(secret){let n=0;const orders=new Map(),payments=new Map();return {keyId:'rzp_test_fixture',credentials(){},async create(amount){const order={id:'order_qa_'+(++n),amount,currency:'INR'};orders.set(order.id,order);return order;},async payment(id){return payments.get(id)||{};},async payments(id){return {items:[...payments.values()].filter(x=>x.order_id===id)};},capture(orderId){const order=orders.get(orderId);if(!order)throw Error('Unknown fixture order');const pid='pay_'+orderId;payments.set(pid,{id:pid,order_id:orderId,amount:order.amount,currency:'INR',status:'captured'});return {razorpay_order_id:orderId,razorpay_payment_id:pid,razorpay_signature:createHmac('sha256',secret).update(orderId+'|'+pid).digest('hex')};}};}
export const fixtureSDK=`window.Razorpay=class{constructor(options){this.options=options;}on(){}open(){const ids=JSON.parse(sessionStorage.getItem('qa-open-orders')||'[]');ids.push(this.options.order_id);sessionStorage.setItem('qa-open-orders',JSON.stringify(ids));const dialog=document.createElement('dialog');dialog.className='razorpay-container';dialog.innerHTML='<h2>ISOLATED PAYMENT FIXTURE</h2><p>No provider request or real payment</p><button>Capture fixture payment</button>';document.body.append(dialog);dialog.showModal();dialog.querySelector('button').onclick=async()=>{const r=await fetch('/__qa/capture',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({orderId:this.options.order_id})});const data=await r.json();dialog.close();dialog.remove();await this.options.handler(data);};}};`;
